headers = {'User-Agent': 'geo-distance-analysis/1.0 (educational)'}
queries = [
    "Glide Memorial Church, 330 Ellis Street, San Francisco, CA",
    "Asian Art Museum, 200 Larkin Street, San Francisco, CA",
    "Market Street & Castro Street, San Francisco, CA",
]
res = {}
for q in queries:
    try:
        r = requests.get("https://nominatim.openstreetmap.org/search",
                         params={'q': q, 'format': 'json', 'limit': 3},
                         headers=headers, timeout=30)
        data = r.json()
        res[q] = [(d.get('display_name'), float(d['lat']), float(d['lon'])) for d in data]
    except Exception as e:
        res[q] = f"ERROR: {e}"
    time.sleep(1.2)

for k,v in res.items():
    print("==", k)
    print(v[:2] if isinstance(v, list) else v)"}

{"code": "import math, itertools

def hav(p1,p2,R=6371008.8):
    la1,lo1=map(math.radians,p1); la2,lo2=map(math.radians,p2)
    h=math.sin((la2-la1)/2)**2+math.cos(la1)*math.cos(la2)*math.sin((lo2-lo1)/2)**2
    return 2*R*math.asin(math.sqrt(h))

G = {'wiki':(37.78528,-122.41139),'osm':(37.7852316,-122.4114682)}
A = {'wiki':(37.780276,-122.416577),'osm_centroid':(37.780315,-122.415992),'mid':(37.78024,-122.41628)}
C = {'muni_stop':(37.762594,-122.435289),'approx':(37.76230,-122.43500),'latlng_alt':(37.76240,-122.43510)}

rows=[]
for gk,g in G.items():
    for ak,a in A.items():
        for ck,c in C.items():
            d1=hav(g,a); d2=hav(g,c)
            rows.append((gk,ak,ck,d1,d2,d1/d2*100))
for r in sorted(rows,key=lambda x:x[5]):
    print(f"{r[0]:>4} {r[1]:>12} {r[2]:>10}  d1={r[3]:6.0f} m  d2={r[4]:6.0f} m  ratio={r[5]:5.2f}%  round={round(r[5])}")

vals=[r[5] for r in rows]
print("\nmin %.2f max %.2f mean %.2f median %.2f"%(min(vals),max(vals),sum(vals)/len(vals),sorted(vals)[len(vals)//2]))"}

